/* ==========================================================================
   潜台词：左右自适应完美对齐版
   ========================================================================== */
:root {
  --subtext-note-bg: transparent !important;
  --subtext-note-color: inherit !important;
  --subtext-toggle-bg: transparent !important;
}

.msg-subtext-body, 
.msg-subtext-body *, 
.msg-subtext-body::before, 
.msg-subtext-body::after {
  background-image: none !important;
  -webkit-mask-image: none !important;
  mask-image: none !important;
  -webkit-mask-box-image: none !important;
  filter: none !important;
  transform: none !important;
  rotate: none !important;
}
.msg-subtext-body::before, 
.msg-subtext-body::after {
  display: none !important;
  content: none !important;
}

.msg-subtext-chip {
  background: none !important;
  background-image: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin-bottom: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  width: 100% !important;
  position: relative !important;
  z-index: 20 !important;
  font-style: normal !important;
}

/* 1. 未展开间距 */
.msg-subtext-chip:not(.is-open) {
  margin-top: -2px !important;
}

/* 2. 展开间距 */
.msg-subtext-chip.is-open {
  margin-top: 0px !important;
}

/* 对方消息（左侧）：靠左排布 */
.msg-them .msg-subtext-chip {
  align-items: flex-start !important;
}

/* 我方消息（右侧）：靠右排布 */
.msg-me .msg-subtext-chip {
  align-items: flex-end !important;
}

.msg-subtext-toggle svg {
  display: none !important;
}

.msg-subtext-toggle {
  order: 2 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 2px 4px !important;
  margin-bottom: 0 !important;
  cursor: pointer !important;
  display: inline-flex !important;
  align-items: center !important;
  font-style: normal !important;
  line-height: 1 !important;
  transform: none !important;
  white-space: nowrap !important;
}

/* 3. 展开后收起按钮与潜台词间距 */
.msg-subtext-chip.is-open .msg-subtext-toggle {
  margin-top: -8px !important;
}

/* 对方收起按钮：左边距微调对齐 */
.msg-them .msg-subtext-toggle {
  margin-left: 30px !important;
  margin-right: 0 !important;
}

/* 我方收起按钮：右边距微调对齐 */
.msg-me .msg-subtext-toggle {
  margin-right: 30px !important;
  margin-left: 0 !important;
}

/* 未展开状态：白光呼吸灯 */
.msg-subtext-chip:not(.is-open) .msg-subtext-toggle::after {
  content: "· 未尽之言" !important;
  font-size: 11px !important;
  font-weight: 500 !important;
  font-style: normal !important;
  color: #ffffff !important;
  letter-spacing: 0.5px !important;
  white-space: nowrap !important;
  animation: nuo-subtext-breathe 2.4s ease-in-out infinite !important;
}

@keyframes nuo-subtext-breathe {
  0%, 100% {
    opacity: 0.5;
    text-shadow: 0 0 2px rgba(255, 255, 255, 0.4), 0 1px 2px rgba(0, 0, 0, 0.6);
  }
  50% {
    opacity: 1;
    text-shadow: 0 0 8px rgba(255, 255, 255, 0.9), 0 0 14px rgba(255, 255, 255, 0.5), 0 1px 2px rgba(0, 0, 0, 0.8);
  }
}

/* 展开状态：“· 收起” */
.msg-subtext-chip.is-open .msg-subtext-toggle::after {
  content: "· 收起" !important;
  font-size: 11px !important;
  font-weight: 500 !important;
  font-style: normal !important;
  color: #ffffff !important;
  opacity: 0.85 !important;
  letter-spacing: 0.5px !important;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.7) !important;
  white-space: nowrap !important;
  animation: none !important;
}

/* 展开时隐藏原气泡 */
.msg-bubble-wrapper:has(.msg-subtext-chip.is-open) .msg-plain-them,
.msg-bubble-wrapper:has(.msg-subtext-chip.is-open) .msg-plain-me {
  display: none !important;
}

/* 潜台词气泡本体 */
.msg-subtext-body {
  order: 1 !important;
  display: none !important;
  position: static !important;
  border-radius: 18px !important;
  box-shadow: none !important;
  padding: 8px 14px !important;
  width: max-content !important;
  max-width: 64vw !important;
  box-sizing: border-box !important;
  font-size: 15px !important;
  line-height: 1.5 !important;
  font-weight: 500 !important;
  white-space: normal !important;
  word-break: break-word !important;
  letter-spacing: normal !important;
  font-style: normal !important;
}

.msg-subtext-chip.is-open .msg-subtext-body {
  display: block !important;
  pointer-events: auto !important;
}

.msg-them .msg-subtext-body {
  background: var(--their-bubble-color) !important;
  backdrop-filter: blur(15px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(15px) saturate(180%) !important;
  border: 0.5px solid rgba(255, 255, 255, 0.5) !important;
  color: var(--their-text-color, #ffffff) !important;
}

.msg-me .msg-subtext-body {
  background: var(--my-bubble-color) !important;
  backdrop-filter: blur(8px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(8px) saturate(180%) !important;
  border: none !important;
  color: var(--my-text-color, #ffffff) !important;
}
